// Collect the "name" column into one actor input (one actor run screens the whole list).
const queries = $input.all().map(i => String(i.json.name || '').trim()).filter(Boolean);
if (queries.length === 0) throw new Error('No names found: the sheet needs a column called "name".');
return [{ json: { input: {
  queries,
  subjectType: 'all',        // 'person' | 'enterprise' | 'all'
  fuzzyThreshold: 0.85,      // raise to reduce possible matches, lower to catch more spelling variants
  maxMatchesPerQuery: 5,
  includeClearQueries: true  // also return one 'clear' row per name with no candidate
}}}];
